def transform(grid):
    g = np.array(grid)
    bg = background(g)
    objs = objects(g, bg=bg, diagonal=True)
    cols = sorted(set(o["colour"] for o in objs))
    # left colour: colour of the object with minimal x
    leftc = min(objs, key=lambda o: (o["box"][1], o["box"][0]))["colour"]
    A = [o for o in objs if o["colour"] == leftc]
    B = [o for o in objs if o["colour"] != leftc]
    A.sort(key=lambda o: (-o["size"], o["box"][0], o["box"][1]))

    def dist(o1, o2):
        return min(max(abs(a[0]-b[0]), abs(a[1]-b[1])) for a in o1["cells"] for b in o2["cells"])

    remaining = list(B)
    pairs = []
    for a in A:
        if remaining:
            b = min(remaining, key=lambda o: dist(a, o))
            remaining.remove(b)
        else:
            b = None
        pairs.append((a, b))
    for b in remaining:
        pairs.append((None, b))

    H, W = g.shape
    out = np.full_like(g, bg)
    emit(out.copy(), "Clear the canvas: every object will be restacked.")
    wA = max([o["box"][3]-o["box"][1]+1 for o in A] or [0])
    xB = wA + 1
    bottoms = {0: H - 1, 1: H - 1}

    def place(o, colx, key):
        y0, x0, y1, x1 = o["box"]
        h = y1 - y0 + 1
        top = bottoms[key] - h + 1
        for (y, x) in o["cells"]:
            ny, nx = top + (y - y0), colx + (x - x0)
            if 0 <= ny < H and 0 <= nx < W:
                out[ny, nx] = o["colour"]
        bottoms[key] = top - 2

    for i, (a, b) in enumerate(pairs):
        if a is not None:
            place(a, 0, 0)
        if b is not None:
            place(b, xB, 1)
        emit(out.copy(), f"Stack pair {i+1} (left colour object and its nearest partner) above the previous ones.")
    return out
